{
  "title": "The Rescue of the Lantern Heir",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "A worn map is unrolled at the edge of the ruined city.",
      "visual_description": "Dawn light over a cracked stone overlook; a tattered map weighted with stones shows the royal city below in fog.",
      "characters": ["Cartographer Maren"]
    },
    {
      "scene_number": 2,
      "caption": "The rescue party gathers at the broken outer wall.",
      "visual_description": "Four figures crouch behind a collapsed buttress, hooded cloaks fluttering, the city's blackened spires rising ahead.",
      "characters": ["Cartographer Maren", "Scout Vey", "Mage Oris", "Sir Halden"]
    },
    {
      "scene_number": 3,
      "caption": "Scout Vey signals that the castle gates are a trap.",
      "visual_description": "From a shadowed alley, Vey points to the looming gilded gates where chains hang suspiciously loose and crows perch on the lintel.",
      "characters": ["Scout Vey", "Sir Halden"]
    },
    {
      "scene_number": 4,
      "caption": "A frightened baker warns them about the patrols.",
      "visual_description": "A flour-dusted woman peers from a half-shuttered doorway, gesturing urgently at boot prints in the ash-strewn street.",
      "characters": ["Goodwife Pell", "Cartographer Maren"]
    },
    {
      "scene_number": 5,
      "caption": "Armored patrol marches past their hiding place.",
      "visual_description": "Black-plated soldiers with crimson sashes stride down a colonnade; the party presses flat behind a toppled statue of a king.",
      "characters": ["Scout Vey", "Sir Halden", "Mage Oris", "Cartographer Maren"]
    },
    {
      "scene_number": 6,
      "caption": "Mage Oris dismisses the rumor of dragons in the cathedral.",
      "visual_description": "Oris waves a glowing hand at distant smoke curling from a cathedral dome, smirking; the others look unconvinced.",
      "characters": ["Mage Oris", "Sir Halden", "Scout Vey"]
    },
    {
      "scene_number": 7,
      "caption": "They find old royal banners stacked in a forgotten armory.",
      "visual_description": "Dusty sun shafts illuminate moth-eaten gold-and-blue banners draped over rusted racks of pikes in a stone vault.",
      "characters": ["Sir Halden", "Cartographer Maren"]
    },
    {
      "scene_number": 8,
      "caption": "Sir Halden refuses to take the bait of the cursed tower.",
      "visual_description": "A leaning obsidian tower glimmers with green witchlight in the windows; Halden lowers his sword and turns away.",
      "characters": ["Sir Halden", "Mage Oris"]
    },
    {
      "scene_number": 9,
      "caption": "Goodwife Pell sketches a back route through the cellars.",
      "visual_description": "By candlelight in a root cellar, Pell draws lines in spilled flour on a barrel top while the party leans in.",
      "characters": ["Goodwife Pell", "Cartographer Maren", "Scout Vey"]
    },
    {
      "scene_number": 10,
      "caption": "Mage Oris unseals a hidden magic door.",
      "visual_description": "Runes ignite in pale blue along a stone arch as Oris presses both palms to it; dust drifts down from the lintel.",
      "characters": ["Mage Oris", "Sir Halden", "Scout Vey", "Cartographer Maren"]
    },
    {
      "scene_number": 11,
      "caption": "They sneak past a snoring castellan in the keep cellars.",
      "visual_description": "A round official slumps over a wine ledger, keys dangling from his belt; the party tiptoes past with held breath.",
      "characters": ["Castellan Brundt", "Scout Vey", "Sir Halden"]
    },
    {
      "scene_number": 12,
      "caption": "They discover the captive heir behind enchanted bars.",
      "visual_description": "A young figure in tattered finery sits in a cell of humming silver bars in a vaulted chamber lit by violet sconces.",
      "characters": ["Prince Alaric", "Sir Halden", "Mage Oris"]
    },
    {
      "scene_number": 13,
      "caption": "Mage Oris breaks the binding spell on the cell.",
      "visual_description": "Silver bars shatter into motes of light; Oris staggers as Halden steadies him and Alaric scrambles free.",
      "characters": ["Mage Oris", "Sir Halden", "Prince Alaric"]
    },
    {
      "scene_number": 14,
      "caption": "Alarm bells ring across the broken city.",
      "visual_description": "View from a balcony: bells swinging in a cracked tower, torches igniting along distant ramparts, ravens scattering.",
      "characters": ["Scout Vey", "Prince Alaric", "Cartographer Maren"]
    },
    {
      "scene_number": 15,
      "caption": "Armored patrols converge in the plaza below.",
      "visual_description": "From a rooftop the party watches columns of black-plate soldiers funnel between fountains choked with weeds.",
      "characters": ["Sir Halden", "Scout Vey", "Prince Alaric", "Mage Oris", "Cartographer Maren"]
    },
    {
      "scene_number": 16,
      "caption": "Scout Vey leaps across rooftops to reach the bridge road.",
      "visual_description": "Vey vaults a gap between tiled rooftops at sunset, rope trailing back to the others waiting on a chimney stack.",
      "characters": ["Scout Vey", "Prince Alaric"]
    },
    {
      "scene_number": 17,
      "caption": "Sir Halden holds the bridge gate against pursuers.",
      "visual_description": "On a narrow stone bridge over a black river, Halden plants himself with shield raised as torches surge up behind him.",
      "characters": ["Sir Halden", "Mage Oris"]
    },
    {
      "scene_number": 18,
      "caption": "The party escapes across the bridge as dawn breaks.",
      "visual_description": "Silhouetted figures hurry across the long stone bridge into golden mist; the ruined city smolders behind them.",
      "characters": ["Sir Halden", "Scout Vey", "Mage Oris", "Cartographer Maren", "Prince Alaric", "Goodwife Pell"]
    }
  ]
}

